<template><div class="gva-form-box wallet-page"><div class="page-head"><div><h2>钱包与运营审计</h2><p>查看钱包、签到与邀请奖励事实记录。</p></div><el-button :icon="Refresh" @click="load">刷新</el-button></div><el-tabs v-model="activeTab" @tab-change="load"><el-tab-pane label="钱包概览" name="wallet"><div class="toolbar"><el-input v-model="keyword" clearable placeholder="读者账号或昵称" @keyup.enter="load"/><el-button :icon="Search" @click="load">查询</el-button></div><el-table v-table-display v-loading="loading" :data="rows" border><el-table-column label="读者 ID" min-width="180"><template #default="{row}"><code>{{row.readerId}}</code></template></el-table-column><el-table-column prop="readerUsername" label="读者" min-width="150"/><el-table-column prop="rechargeBalance" label="充值余额" width="130"/><el-table-column prop="bonusBalance" label="奖励余额" width="130"/><el-table-column label="操作" width="150"><template #default="{row}"><el-button link type="primary" @click="showLedgers(row)">流水</el-button><el-button link type="warning" @click="openAdjust(row)">调账</el-button></template></el-table-column></el-table><div class="pager"><el-pagination v-model:current-page="page" v-model:page-size="pageSize" :total="total" layout="total, sizes, prev, pager, next" @size-change="load" @current-change="load"/></div></el-tab-pane><el-tab-pane label="签到记录" name="checkins"><div class="toolbar"><el-input v-model="checkin.readerKeyword" clearable placeholder="读者账号或昵称"/><el-date-picker v-model="checkin.startDate" type="date" value-format="YYYY-MM-DD" placeholder="开始日期"/><el-date-picker v-model="checkin.endDate" type="date" value-format="YYYY-MM-DD" placeholder="结束日期"/><el-button :icon="Search" @click="loadCheckins">查询</el-button></div><el-table v-table-display v-loading="checkin.loading" :data="checkin.rows" border><el-table-column prop="checkinDate" label="签到日期" min-width="185" :formatter="adminTimeColumn" /><el-table-column label="读者" min-width="180"><template #default="{row}"><span>{{row.username || '-'}}</span><code>{{row.readerId}}</code></template></el-table-column><el-table-column prop="continuousDays" label="连续天数" width="100"/><el-table-column prop="totalRewardCoin" label="总奖励" width="100"/><el-table-column prop="createdAt" label="记录时间" min-width="185" :formatter="adminTimeColumn" /></el-table><div class="pager"><el-pagination v-model:current-page="checkin.page" v-model:page-size="checkin.pageSize" :total="checkin.total" layout="total, prev, pager, next" @current-change="loadCheckins"/></div></el-tab-pane><el-tab-pane label="邀请奖励" name="rewards"><div class="toolbar"><el-input v-model="reward.inviterKeyword" clearable placeholder="邀请人账号或昵称"/><el-input v-model="reward.inviteeKeyword" clearable placeholder="被邀请人账号或昵称"/><el-select v-model="reward.rewardStage" clearable placeholder="奖励阶段"><el-option label="注册" value="register"/><el-option label="首充" value="first_recharge"/></el-select><el-select v-model="reward.status" clearable placeholder="状态"><el-option label="已发放" value="granted"/><el-option label="已跳过" value="skipped"/><el-option label="失败" value="failed"/></el-select><el-button :icon="Search" @click="loadRewards">查询</el-button></div><el-table v-table-display v-loading="reward.loading" :data="reward.rows" border><el-table-column label="邀请人" min-width="180"><template #default="{row}"><span>{{row.inviterUsername || '-'}}</span><code>{{row.inviterReaderId}}</code></template></el-table-column><el-table-column label="被邀请人" min-width="180"><template #default="{row}"><span>{{row.inviteeUsername || '-'}}</span><code>{{row.inviteeReaderId}}</code></template></el-table-column><el-table-column prop="rewardStage" label="阶段" width="120"/><el-table-column prop="rewardCoin" label="奖励" width="100"/><el-table-column prop="status" label="状态" width="100" :formatter="adminStatusColumn" /><el-table-column prop="grantedAt" label="发放时间" min-width="185" :formatter="adminTimeColumn" /><el-table-column prop="remark" label="备注" min-width="160"/></el-table><div class="pager"><el-pagination v-model:current-page="reward.page" v-model:page-size="reward.pageSize" :total="reward.total" layout="total, prev, pager, next" @current-change="loadRewards"/></div></el-tab-pane></el-tabs><el-drawer v-model="drawer" title="钱包流水" size="760px"><el-table v-table-display v-loading="ledgerLoading" :data="ledgers" border><el-table-column prop="id" label="流水 ID"/><el-table-column prop="ledgerNo" label="流水号"/><el-table-column prop="direction" label="方向"/><el-table-column prop="coinType" label="币种"/><el-table-column prop="amount" label="金额"/><el-table-column prop="balanceAfter" label="变更后"/><el-table-column prop="bizType" label="业务"/><el-table-column prop="createdAt" label="时间" :formatter="adminTimeColumn" /></el-table></el-drawer><el-dialog v-model="adjustDialog" title="人工调整钱包" width="480px"><el-form ref="adjustRef" :model="adjustForm" :rules="adjustRules" label-position="top"><el-form-item label="读者"><el-input :model-value="adjustReaderLabel" disabled/></el-form-item><el-form-item label="币种" prop="coinType"><el-select v-model="adjustForm.coinType"><el-option label="充值币" value="recharge"/><el-option label="奖励币" value="bonus"/></el-select></el-form-item><el-form-item label="方向" prop="direction"><el-select v-model="adjustForm.direction"><el-option label="收入" value="income"/><el-option label="支出" value="expense"/></el-select></el-form-item><el-form-item label="金额" prop="amount"><el-input v-model="adjustForm.amount" inputmode="numeric"/></el-form-item><el-form-item label="调整原因" prop="reason"><el-input v-model="adjustForm.reason" maxlength="255"/></el-form-item><el-form-item label="请求 ID" prop="requestId"><el-input v-model="adjustForm.requestId" maxlength="64"/></el-form-item></el-form><template #footer><el-button @click="adjustDialog=false">取消</el-button><el-button type="primary" :loading="adjustSaving" @click="saveAdjust">保存</el-button></template></el-dialog></div></template>
<script setup>
import { adminStatusColumn, adminTimeColumn } from '@/utils/adminDisplay'
import { reactive, ref } from 'vue'; import { Refresh, Search } from '@element-plus/icons-vue'; import { ElMessage } from 'element-plus'; import { adjustReaderWallet, listReaderWalletLedgers, listReaderWallets, listReaderCheckins, listReaderInviteRewards } from '@/api/reader/walletAdmin'
defineOptions({ name:'ReaderWallet' }); const activeTab=ref('wallet'); const rows=ref([]); const total=ref(0); const page=ref(1); const pageSize=ref(20); const keyword=ref(''); const loading=ref(false); const drawer=ref(false); const ledgerLoading=ref(false); const ledgers=ref([]); const adjustDialog=ref(false); const adjustSaving=ref(false); const adjustRef=ref(); const adjustReaderId=ref(''); const adjustReaderLabel=ref(''); const adjustForm=reactive({coinType:'recharge',direction:'income',amount:'',reason:'',requestId:''}); const adjustRules={amount:[{required:true,pattern:/^[1-9]\d*$/,message:'请输入正整数',trigger:'blur'}],reason:[{required:true,message:'请输入调整原因',trigger:'blur'}],requestId:[{required:true,message:'请输入请求 ID',trigger:'blur'}]}; const checkin=reactive({readerKeyword:'',startDate:'',endDate:'',page:1,pageSize:20,total:0,rows:[],loading:false}); const reward=reactive({inviterKeyword:'',inviteeKeyword:'',rewardStage:'',status:'',page:1,pageSize:20,total:0,rows:[],loading:false})
const load=async()=>{if(activeTab.value==='checkins')return loadCheckins();if(activeTab.value==='rewards')return loadRewards();loading.value=true;try{const r=await listReaderWallets({keyword:keyword.value,page:page.value,pageSize:pageSize.value});rows.value=r.data?.list||[];total.value=r.data?.total||0}finally{loading.value=false}}; const loadCheckins=async()=>{checkin.loading=true;try{const r=await listReaderCheckins({readerKeyword:checkin.readerKeyword,startDate:checkin.startDate,endDate:checkin.endDate,page:checkin.page,pageSize:checkin.pageSize});checkin.rows=r.data?.list||[];checkin.total=r.data?.total||0}finally{checkin.loading=false}}; const loadRewards=async()=>{reward.loading=true;try{const r=await listReaderInviteRewards({inviterKeyword:reward.inviterKeyword,inviteeKeyword:reward.inviteeKeyword,rewardStage:reward.rewardStage,status:reward.status,page:reward.page,pageSize:reward.pageSize});reward.rows=r.data?.list||[];reward.total=r.data?.total||0}finally{reward.loading=false}}; const showLedgers=async(row)=>{drawer.value=true;ledgerLoading.value=true;try{const r=await listReaderWalletLedgers(row.readerId,{page:1,pageSize:100});ledgers.value=r.data?.list||[]}finally{ledgerLoading.value=false}}; const openAdjust=(row)=>{adjustReaderId.value=row.readerId;adjustReaderLabel.value=`${row.readerUsername}（${row.readerId}）`;adjustDialog.value=true}; const saveAdjust=async()=>{if(!(await adjustRef.value?.validate().catch(()=>false)))return;adjustSaving.value=true;try{await adjustReaderWallet(adjustReaderId.value,{...adjustForm});ElMessage.success('调账成功');adjustDialog.value=false;await load()}finally{adjustSaving.value=false}}; load()
</script><style scoped>.wallet-page{padding:20px}.page-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}.page-head h2{margin:0}.page-head p{margin:6px 0;color:var(--el-text-color-secondary)}.toolbar{display:flex;gap:10px;margin-bottom:14px;flex-wrap:wrap}.toolbar .el-input{max-width:240px}.pager{display:flex;justify-content:flex-end;margin-top:16px}code{display:block;font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:12px;color:var(--el-text-color-secondary)}</style>
